mapper.update:
UPDATE ai_code_project
name = #{name}, git_url = #{gitUrl}, git_branch = #{gitBranch}, credential_enc = #{credentialEnc}, credential_user = #{credentialUser}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE ai_code_project
SET status = #{status}, last_error = NULL, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE ai_code_project
SET status = #{status}, git_commit = #{gitCommit}, last_error = NULL,
    last_indexed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
    last_index_ms = #{durationMs}
WHERE id = #{id}

UPDATE ai_code_project
SET status = 'FAILED', last_error = #{error}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
